import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.some.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
export default {
  mixins: [get_all_org_users],
  data() {
    return {
      checklist: {},
      selectedUser: null,
      userHeaders: [{
        text: "",
        value: "userDetail",
        sortable: false
      }],
      CardValue: 1,
      selectedStatus: null,
      name: "",
      filterMenu: false,
      filterOptions: [{
        text: "All",
        value: null
      }, {
        text: "Yet to start",
        value: "PENDING"
      }, {
        text: "Started",
        value: "STARTED"
      }, {
        text: "Completed",
        value: "COMPLETED"
      }]
    };
  },
  async created() {
    const data = this.$store.getters.GetChecklist;
    // console.log("Checklist from store:", data);
    this.checklist = data || {};
    await this.get_all_org_users();
    this.fetch_user_list();
  },
  computed: {
    visibleMembers() {
      if (!this.orgUsers) return [];
      if (!this.checklist.checklist_visible_members || this.checklist.checklist_visible_members.length === 0) {
        return this.orgUsers.filter(user => user.user_status === "ACTIVE");
      }
      return this.checklist.checklist_visible_members.map(id => this.orgUsers.find(u => u.user_id === id)).filter(Boolean);
    },
    groupedSections() {
      const out = {};
      const details = this.checklist?.checklist_details || {};
      Object.entries(details).forEach(([sectionName, arr]) => {
        if (sectionName !== "line_items") {
          out[sectionName.trim()] = arr.filter(t => t.section_type === "section");
        }
      });
      return out;
    },
    lineItems() {
      const li = this.checklist?.checklist_details?.line_items || [];
      return li.filter(t => t.section_type === "line_item");
    },
    filteredGroupedSections() {
      const filtered = {};
      for (const [section, items] of Object.entries(this.groupedSections)) {
        const matching = items.filter(item => !this.selectedStatus || item.progress_status === this.selectedStatus);
        if (matching.length > 0) {
          filtered[section] = matching;
        }
      }
      return filtered;
    },
    filteredLineItems() {
      return this.lineItems.filter(li => !this.selectedStatus || li.progress_status === this.selectedStatus);
    },
    groupedSections1() {
      if (!this.selectedUser || !this.selectedUser.checklist_details) {
        return {};
      }
      const sections = {};
      for (const [sectionTitle, tasks] of Object.entries(this.selectedUser.checklist_details)) {
        const sectionTasks = tasks.filter(t => t.section_type === "section");
        if (sectionTasks.length > 0) {
          sections[sectionTitle] = sectionTasks;
        }
      }
      return sections;
    },
    lineItems1() {
      if (!this.selectedUser || !this.selectedUser.checklist_details) {
        return [];
      }
      const items = [];
      for (const tasks of Object.values(this.selectedUser.checklist_details)) {
        items.push(...tasks.filter(t => t.section_type === "line_item"));
      }
      return items;
    },
    hasTasks() {
      const hasSections = this.groupedSections1 && Object.values(this.groupedSections1).some(tasks => tasks.length > 0);
      const hasLineItems = this.lineItems1 && this.lineItems1.length > 0;
      return hasSections || hasLineItems;
    }
  },
  methods: {
    formatdisplayDates(date) {
      return formatdisplayDate(date);
    },
    fetch_user_list() {
      this.userProfiles = {};
      localStorage.setItem("allOrgUsers", JSON.stringify(this.orgUsers));
      this.orgUsers.forEach(element => {
        if (element.user_status === "ACTIVE") {
          const email = element.user_email_id;
          const profilePicUrl = element.user_profile_pic_url || "";
          const name = element.full_user_name;
          if (profilePicUrl && profilePicUrl !== "N/A") {
            this.userProfiles[email] = profilePicUrl;
          } else {
            const initials = this.getInitials(name);
            this.userProfiles[email] = initials;
          }
        }
      });
    },
    getInitials(name) {
      if (typeof name !== "string" || name.trim() === "") {
        return "N/A";
      }
      const initials = name.charAt(0).toUpperCase();
      return initials || "N/A";
    },
    hasValidPic(url) {
      return url && url !== "N/A";
    },
    getColor(name) {
      if (!name || typeof name !== "string") {
        return "grey lighten-2"; // Default color for undefined/null names
      }
      const palette = ["indigo lighten-2", "deep-orange lighten-2", "teal lighten-2", "blue lighten-2", "green lighten-2", "purple lighten-2", "cyan lighten-2", "pink lighten-2"];
      let hash = 0;
      for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
      }
      return palette[Math.abs(hash) % palette.length];
    },
    getProgressColor(value) {
      if (value < 40) return "red";
      if (value < 80) return "blue";
      if (value === 100) return "green";
      return "orange";
    },
    handleUserSelect(click, value) {
      const item = value.item;
      if (!this.checklist || !this.checklist.checklist_details) return;
      const userKey = item.full_user_name?.trim().toLowerCase();
      const checklistDetails = this.checklist.checklist_details;
      const filteredChecklist = {};
      Object.entries(checklistDetails).forEach(([sectionName, items]) => {
        if (Array.isArray(items)) {
          const matchedItems = items.filter(entry => entry.assigned_to_name?.trim().toLowerCase() === userKey);
          if (matchedItems.length > 0) {
            filteredChecklist[sectionName] = matchedItems;
          }
        }
      });
      const selectedData = {
        ...item,
        checklist_details: filteredChecklist
      };
      this.selectUser(selectedData);
    },
    selectUser(userData) {
      this.selectedUser = userData;
      this.CardValue = 2;
    },
    rowClass(item) {
      return this.selectedUser && this.selectedUser.full_user_name === item.full_user_name ? "selected-row" : "";
    },
    formatDate(ts) {
      if (!ts) return "—";
      return new Date(ts * 1000).toLocaleDateString(undefined, {
        year: "numeric",
        month: "short",
        day: "numeric"
      });
    },
    firstLetter(name) {
      return name ? name.charAt(0).toUpperCase() : "?";
    },
    close_card() {
      this.$router.push("/home/CheckList");
    },
    filteredTasks(items) {
      if (!this.selectedStatus) return items;
      return items.filter(task => task.progress_status === this.selectedStatus);
    },
    getStatusText(status) {
      switch (status) {
        case "PENDING":
          return "Yet to Start";
        case "STARTED":
          return "Started";
        case "COMPLETED":
          return "Completed";
        case "NOT_APPLICABLE":
          return "Not Applicable";
        default:
          return status;
      }
    },
    getStatusChipClass(status) {
      if (!status) {
        return "grey lighten-3 grey--text";
      }
      switch (status.toUpperCase()) {
        case "COMPLETED":
          return "success lighten-4 success--text";
        case "STARTED":
          return "warning lighten-4 warning--text";
        case "PENDING":
          return "error lighten-4 error--text";
        case "NOT_APPLICABLE":
          return "info lighten-4 info--text";
        default:
          return "grey lighten-3 grey--text";
      }
    }
  }
};
